/**
 * Campaign 001 — disposable PostgreSQL 16 database.
 *
 * Every test run owns one freshly created database on a loopback
 * PostgreSQL 16 server, brings the schema up with the application's own
 * TypeORM migrations under explicit control, and drops that database at the
 * end. Nothing else on the server is touched.
 *
 * Safety properties enforced here, not by convention:
 *   - the admin target must be a loopback host;
 *   - the server must be PostgreSQL major version 16 (the recorded
 *     production version is 16.14);
 *   - the database name is generated by this class and must match
 *     DISPOSABLE_NAME_PATTERN before any CREATE or DROP is issued;
 *   - DROP only ever targets the name this instance created;
 *   - synchronize and migrationsRun are hard-coded off; migrations run
 *     only through runMigrations(), which returns the executed names.
 */
import { randomBytes } from 'crypto';
import { join } from 'path';
import { Client } from 'pg';
import { DataSource } from 'typeorm';

export const DISPOSABLE_NAME_PATTERN = /^crm_test_\d{8}_\d{6}_[a-f0-9]{6}$/;
const LOOPBACK_HOSTS = new Set(['127.0.0.1', 'localhost', '::1']);
const REQUIRED_PG_MAJOR = 16;

/** Absolute path of crm-v2-server/src, derived from this file's location. */
export const SRC_DIR = join(__dirname, '..', '..', '..', 'src');

export interface AdminTarget {
  host: string;
  port: number;
  user: string;
  password: string;
  maintenanceDb: string;
}

export class UnsafeDatabaseTargetError extends Error {
  constructor(message: string) {
    super(`Refusing database operation: ${message}`);
    this.name = 'UnsafeDatabaseTargetError';
  }
}

export function assertLoopbackHost(host: string): void {
  if (!LOOPBACK_HOSTS.has(host)) {
    throw new UnsafeDatabaseTargetError(
      `host "${host}" is not a loopback address; the harness only uses a local disposable server`,
    );
  }
}

export interface ServerIdentity {
  server_addr: string | null;
  server_port: number | null;
  data_directory: string;
  listen_addresses: string;
}

/** Windows drive-letter or POSIX absolute path on THIS machine; never a UNC/network path. */
const LOCAL_DATA_DIR = /^([A-Za-z]:[\\/]|\/)(?![\\/])/;

export function assertServerIsLocal(id: ServerIdentity): void {
  if (!id.server_addr || !LOOPBACK_HOSTS.has(id.server_addr.replace(/\/\d+$/, ''))) {
    throw new UnsafeDatabaseTargetError(
      `the server reports its own address as "${id.server_addr}", which is not loopback`,
    );
  }
  if (!LOCAL_DATA_DIR.test(id.data_directory) || id.data_directory.startsWith('\\\\') || id.data_directory.startsWith('//')) {
    throw new UnsafeDatabaseTargetError(
      `the server's data directory "${id.data_directory}" is not a local path on this machine`,
    );
  }
}

export function assertDisposableName(name: string): void {
  if (!DISPOSABLE_NAME_PATTERN.test(name)) {
    throw new UnsafeDatabaseTargetError(
      `database name "${name}" was not generated by this harness`,
    );
  }
}

/**
 * Reads the admin connection for the local disposable server from
 * CRM_TEST_PG_* only. These are deliberately NOT the application's
 * DATABASE_* names so the two can never be confused.
 */
export function readAdminTarget(env: NodeJS.ProcessEnv = process.env): AdminTarget {
  const host = env.CRM_TEST_PG_HOST || '127.0.0.1';
  const port = Number(env.CRM_TEST_PG_PORT || '5433');
  const user = env.CRM_TEST_PG_ADMIN_USER || 'postgres';
  const password = env.CRM_TEST_PG_ADMIN_PASSWORD;
  assertLoopbackHost(host);
  if (!Number.isInteger(port) || port <= 0 || port > 65535) {
    throw new UnsafeDatabaseTargetError(`port "${env.CRM_TEST_PG_PORT}" is not valid`);
  }
  if (!password) {
    throw new UnsafeDatabaseTargetError(
      'CRM_TEST_PG_ADMIN_PASSWORD is not set; the harness never falls back to a default or to DATABASE_PASSWORD',
    );
  }
  return { host, port, user, password, maintenanceDb: 'postgres' };
}

function timestampToken(d = new Date()): string {
  const p = (n: number, w = 2) => String(n).padStart(w, '0');
  return (
    `${d.getUTCFullYear()}${p(d.getUTCMonth() + 1)}${p(d.getUTCDate())}` +
    `_${p(d.getUTCHours())}${p(d.getUTCMinutes())}${p(d.getUTCSeconds())}`
  );
}

export function generateDisposableName(): string {
  const name = `crm_test_${timestampToken()}_${randomBytes(3).toString('hex')}`;
  assertDisposableName(name);
  return name;
}

async function withAdminClient<T>(
  target: AdminTarget,
  fn: (client: Client) => Promise<T>,
): Promise<T> {
  const client = new Client({
    host: target.host,
    port: target.port,
    user: target.user,
    password: target.password,
    database: target.maintenanceDb,
    connectionTimeoutMillis: 5000,
  });
  await client.connect();
  try {
    return await fn(client);
  } finally {
    await client.end();
  }
}

export class DisposableDatabase {
  private dropped = false;

  private constructor(
    public readonly target: AdminTarget,
    public readonly name: string,
    public readonly serverVersion: string,
    /** What the server itself reported about where it is (production-isolation gate evidence). */
    public readonly serverIdentity: ServerIdentity,
  ) {}

  /**
   * Creates a new empty database on the loopback PG16 server.
   *
   * Production-isolation gate: beyond checking the host string we asked for,
   * the SERVER is asked where it is. inet_server_addr() must be a loopback
   * address and the data directory must be on this machine, or we stop.
   */
  static async create(target: AdminTarget = readAdminTarget()): Promise<DisposableDatabase> {
    assertLoopbackHost(target.host);
    const name = generateDisposableName();
    const { version, identity } = await withAdminClient(target, async (client) => {
      const res = await client.query<{ server_version: string }>('show server_version');
      const version = res.rows[0].server_version;
      const major = Number(version.split('.')[0]);
      if (major !== REQUIRED_PG_MAJOR) {
        throw new UnsafeDatabaseTargetError(
          `server is PostgreSQL ${version}; the harness requires major version ${REQUIRED_PG_MAJOR}`,
        );
      }
      const who = await client.query<ServerIdentity>(
        `select inet_server_addr()::text as server_addr,
                inet_server_port() as server_port,
                current_setting('data_directory') as data_directory,
                current_setting('listen_addresses') as listen_addresses`,
      );
      const identity = who.rows[0];
      assertServerIsLocal(identity);
      const exists = await client.query('select 1 from pg_database where datname = $1', [name]);
      if (exists.rowCount) {
        throw new UnsafeDatabaseTargetError(`database "${name}" already exists`);
      }
      assertDisposableName(name);
      await client.query(`CREATE DATABASE "${name}"`);
      return { version, identity };
    });
    return new DisposableDatabase(target, name, version, identity);
  }

  /** TypeORM connection options for the disposable database; never synchronize. */
  connectionOptions() {
    return {
      type: 'postgres' as const,
      host: this.target.host,
      port: this.target.port,
      username: this.target.user,
      password: this.target.password,
      database: this.name,
      synchronize: false as const,
      migrationsRun: false as const,
      logging: false as const,
    };
  }

  /**
   * Runs the application's migration files against this database only and
   * returns the migration names in execution order. This is the only way
   * schema reaches a disposable database.
   */
  async runMigrations(): Promise<string[]> {
    assertDisposableName(this.name);
    const ds = new DataSource({
      ...this.connectionOptions(),
      entities: [join(SRC_DIR, '**', '*.entity{.ts,.js}')],
      migrations: [join(SRC_DIR, 'database', 'migrations', '*{.ts,.js}')],
    });
    await ds.initialize();
    try {
      const executed = await ds.runMigrations({ transaction: 'each' });
      return executed.map((m) => m.name);
    } finally {
      await ds.destroy();
    }
  }

  /** Names recorded in the migrations table of this database. */
  async appliedMigrationNames(): Promise<string[]> {
    const client = new Client({ ...this.target, database: this.name });
    await client.connect();
    try {
      const res = await client.query<{ name: string }>(
        'select name from migrations order by id',
      );
      return res.rows.map((r) => r.name);
    } finally {
      await client.end();
    }
  }

  /** Drops this database and nothing else. Idempotent. */
  async drop(): Promise<void> {
    if (this.dropped) return;
    assertDisposableName(this.name);
    await withAdminClient(this.target, async (client) => {
      await client.query(`DROP DATABASE IF EXISTS "${this.name}" WITH (FORCE)`);
    });
    this.dropped = true;
  }
}
